cd /workspace && node -e "
const { resolveSession } = require('./src/session.js');

async function main() {
  let loadCount = 0;
  const ioA = { loadSession: async (id) => { loadCount++; await new Promise(r => setTimeout(r, 5)); return { id, tenant: 'A' }; } };

  // 1. sequential memoization
  const s1 = await resolveSession(ioA, 's1');
  const s1b = await resolveSession(ioA, 's1');
  console.log('sequential memoized:', s1 === s1b, 'loadCount =', loadCount); // expect true, 1

  // 2. concurrency coalescing (same session, parallel)
  loadCount = 0;
  const [c1, c2, c3] = await Promise.all([
    resolveSession(ioA, 's2'), resolveSession(ioA, 's2'), resolveSession(ioA, 's2')
  ]);
  console.log('concurrent coalesced:', c1 === c2 && c2 === c3, 'loadCount =', loadCount); // expect true, 1

  // 3. per-tenant (per-io) isolation
  const ioB = { loadSession: async (id) => { return { id, tenant: 'B' }; } };
  const a = await resolveSession(ioA, 's1');
  const b = await resolveSession(ioB, 's1');
  console.log('per-io isolated:', a.tenant === 'A' && b.tenant === 'B'); // expect true

  // 4. failures are not cached (retry happens)
  let fail = true; let retried = 0;
  const ioC = { loadSession: async (id) => { retried++; if (fail) { fail = false; throw new Error('boom'); } return { ok: true }; } };
  let rejected = false;
  try { await resolveSession(ioC, 'x'); } catch (e) { rejected = true; }
  const after = await resolveSession(ioC, 'x');
  console.log('failure retried:', rejected && after.ok === true, 'loadCount =', retried); // expect true, 2

  // 5. falsy session value handled
  const ioD = { loadSession: async () => null };
  let n = 0;
  const ioE = { loadSession: async () => { n++; return null; } };
  const v1 = await resolveSession(ioE, 'z');
  const v2 = await resolveSession(ioE, 'z');
  console.log('falsy cached:', v1 === null && v2 === null, 'loadCount =', n); // expect true, 1

  // 6. identity: repeated resolves of same session return same object
  const r1 = await resolveSession(ioA, 's1');
  const r2 = await resolveSession(ioA, 's1');
  console.log('identity stable:', r1 === r2);
}
main().catch(e => { console.error('FAIL', e); process.exit(1); });
"

